mapper.insert:
		INSERT INTO PRJ_PRJCT_INFO_TBL (
			PRJCT_CD
		  , PRJCT_TP
		  , PRJCT_STAT_TP
		  , PRJCT_DPLY_TP
		  , PRJCT_VRFC_TP
		  , PRJCT_CPTB_TP
		  , USE_YN
		  , PRJCT_NM
		  , PRJCT_STRT_DT
		  , PRJCT_END_DT
		  , PRJCT_DESC 
		  , ETC
		  , RGST_DT
		  , RGST_SEQ
		  , RGST_NM
		)
		VALUES (
			#{prjctCd, jdbcType=VARCHAR}
		  , #{prjctTp, jdbcType=VARCHAR}
		  , #{prjctStatTp, jdbcType=VARCHAR}
 		  , (
				CASE
					WHEN (#{prjctDplyTp, jdbcType=VARCHAR} IS NULL OR #{prjctDplyTp, jdbcType=VARCHAR} = '') THEN '99'
					ELSE    #{prjctDplyTp, jdbcType=VARCHAR}
				END
			)
		  , (
				CASE
					WHEN (#{prjctVrfcTp, jdbcType=VARCHAR} IS NULL OR #{prjctVrfcTp, jdbcType=VARCHAR} = '') THEN '99'
					ELSE    #{prjctVrfcTp, jdbcType=VARCHAR}
				END
		 	)
		  , (
				CASE
					WHEN (#{prjctCptbTp, jdbcType=VARCHAR} IS NULL OR #{prjctCptbTp, jdbcType=VARCHAR} = '') THEN '99'
					ELSE    #{prjctCptbTp, jdbcType=VARCHAR}
				END
		 	)
		  , (
				CASE
					WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
					ELSE    #{useYn, jdbcType=VARCHAR}
				END
		   )	
		  , #{prjctNm, jdbcType=VARCHAR}
		  , (
				CASE
					WHEN (#{prjctStrtDt, jdbcType=VARCHAR} IS NULL OR #{prjctStrtDt, jdbcType=VARCHAR} = '') THEN NULL
					ELSE    TO_DATE(#{prjctStrtDt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
				END
		   )
		  , (
				CASE
					WHEN (#{prjctEndDt, jdbcType=VARCHAR} IS NULL OR #{prjctEndDt, jdbcType=VARCHAR} = '') THEN NULL
					ELSE    TO_DATE(#{prjctEndDt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
				END
		   )
		  , #{prjctDesc, jdbcType=VARCHAR} 
		  , #{etc, jdbcType=VARCHAR} 
		  , CURRENT_TIMESTAMP(3)
		  , #{rgstSeq, jdbcType=NUMERIC}
		  , (
				CASE 
					WHEN (#{rgstNm, jdbcType=VARCHAR} IS NULL OR #{rgstNm, jdbcType=VARCHAR} = '') THEN NULL
					ELSE   #{rgstNm, jdbcType=VARCHAR}
				END
			)	
		)

INSERT INTO PRJ_SITE_PRJCT_MAP (
	PRJCT_SEQ
  , CHNL_SITE_SEQ
  , SRVC_SEQ
  , USE_YN
  , RGST_DT	
  , RGST_SEQ
  , RGST_NM
)
VALUES (
	#{prjctSeq, jdbcType=NUMERIC}
  , #{chnlSiteSeq, jdbcType=NUMERIC}
  , #{srvcSeq, jdbcType=NUMERIC}
  , (
		CASE
			WHEN (#{useYn, jdbcType=VARCHAR} IS NULL OR #{useYn, jdbcType=VARCHAR} = '') THEN 'Y'
			ELSE   #{useYn, jdbcType=VARCHAR}
		END
    )
  ,	CURRENT_TIMESTAMP(3)
  , #{rgstSeq, jdbcType=NUMERIC}
  , #{rgstNm, jdbcType=VARCHAR}
)
